"""Banco de 50 ideias para os próximos dois meses (8 semanas a partir de 26/10/2026), no tom agressivo da série.
Gera um JSON por ideia e o lote de escrita para a coleção `ideias` do Estúdio Escher.
uso: python ideias_50.py <pasta_saida>
"""
import json, os, sys

SEMANAS = ['26 out – 1 nov', '2 – 8 nov', '9 – 15 nov', '16 – 22 nov', '23 – 29 nov', '30 nov – 6 dez', '7 – 13 dez', '14 – 20 dez']

I = []
def idea(id, semana, area, ano, titulo, gancho, porque, ancora, arco, prova, tecnico, humor, imagens, fecho, verificar='', top=False):
    I.append(dict(id=id, semana=semana, periodo=SEMANAS[semana - 1], area=area, ano=ano, titulo=titulo, gancho=gancho, porque=porque, ancora=ancora,
                  arco=arco, prova=prova, tecnico=tecnico, humor=humor, imagens=imagens, fecho=fecho, verificar=verificar, recomendada=top))

